#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// Must be a UPROPERTY: the tracker is created with NewObject and is only
	// kept alive by reflection. A raw pointer here is collected by the GC on
	// the next purge and the following AddPoints() call crashes.
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode::ScoreTracker was a raw UArenaScoreTracker* created with NewObject(this) but not marked UPROPERTY, so no UObject reference kept it alive. The engine's periodic garbage collection (log: 'Collecting garbage: 412 objects purged' at 21:05:13) destroyed the tracker, leaving ScoreTracker dangling. The next goal called ScoreTracker->AddPoints() through the freed object and crashed with EXCEPTION_ACCESS_VIOLATION reading 0xffffffffffffffff (log: AddPoints at ArenaScoreTracker.cpp:18, called from OnGoalScored at ArenaGameMode.cpp:38). Fixed by declaring ScoreTracker as UPROPERTY() TObjectPtr<UArenaScoreTracker> in ArenaGameMode.h and adding an initialization guard in OnGoalScored.",
  "no_colors_cause": "The palette /Game/Data/Palettes/DA_Primary is loaded only by string path at runtime in AArenaGameMode::BeginPlay. Nothing in the Arena map or in any other cooked asset references it, and DefaultGame.ini had bCookAll=False with only /Game/Maps/Arena in MapsToCook and /Game/Data/Effects in DirectoriesToAlwaysCook, so the cooker never included the palette package in the shipping pak. At runtime LoadObject failed ('Couldn't find file for package /Game/Data/Palettes/DA_Primary'), the palette was null, and ArenaGameMode fell back to gray ('Palette is null, using fallback gray'), so the arena rendered without colors. Fixed by adding +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") to Config/DefaultGame.ini."
}
